ArgumentNullException.ThrowIfNull(caminho);
try {
    using var reader = new StreamReader(caminho);
    Console.WriteLine(reader.ReadLine());
} catch (IOException ex) {
    Console.WriteLine(ex.Message);
    throw;
}
